{
  "concepts": [
    {
      "conditions": [],
      "definition": "The cumulative feedback route from current specification through real use, gap analysis, and intake-selected owning-layer re-entry or observation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2956,
          "quote": "Current spec → real-world use case → gap analysis → intake-selected re-entry or observation",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FRenewal%20Path",
          "start_line": 2954
        }
      ],
      "key": "spec_renewal",
      "label": "Renewal Path"
    },
    {
      "conditions": [],
      "definition": "Goals orient the current bounded work wave.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3201,
          "quote": "**Goals** orient the current bounded work wave.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSpecification%20Surface%20Rule",
          "start_line": 3201
        }
      ],
      "key": "spec_goals",
      "label": "Goals"
    },
    {
      "conditions": [],
      "definition": "Intent states why the system exists and which directional changes are within or outside scope.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3202,
          "quote": "**Intent** states why the system exists and what directional change is in or out of scope.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSpecification%20Surface%20Rule",
          "start_line": 3202
        }
      ],
      "key": "spec_intent",
      "label": "Intent"
    },
    {
      "conditions": [],
      "definition": "Product is the current concrete product-definition surface bridging Intent to Requirements.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3203,
          "quote": "**Product** states the current concrete product definition and bridges intent to requirements.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSpecification%20Surface%20Rule",
          "start_line": 3203
        }
      ],
      "key": "spec_product",
      "label": "Product specification surface"
    },
    {
      "conditions": [],
      "definition": "Requirements express stable obligations that must be true, with acceptance criteria sufficient for downstream design derivation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3204,
          "quote": "**Requirements** state stable obligations that must be true.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSpecification%20Surface%20Rule",
          "start_line": 3204
        }
      ],
      "key": "spec_requirements",
      "label": "Requirements"
    },
    {
      "conditions": [],
      "definition": "Design states how requirement truth is realized and owns downstream structural choices.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3205,
          "quote": "**Design** states how requirement truth is realized.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSpecification%20Surface%20Rule",
          "start_line": 3205
        }
      ],
      "key": "spec_design",
      "label": "Design"
    },
    {
      "conditions": [],
      "definition": "Realization is constructed under selected design and execution bindings; code is its software case. It remains governed jointly by Requirements and Design.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3408,
          "quote": "10. Construct the **Realization** under its selected design and execution\n    binding, and reconcile design, realized behavior and applicable proof\n    before promotion or closure. Code is the software case of this step.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FMethod",
          "start_line": 3406
        }
      ],
      "key": "spec_realization",
      "label": "Realization"
    },
    {
      "conditions": [],
      "definition": "Constitutional trace closure connects live obligations to owning realization or explicit unresolved/deferred relations and closes constitutional authority over realized behavior; documentation completeness alone is weaker.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2990,
          "quote": "a live\nobligation needs an owning realization or an explicit unresolved/deferred\nrelation, and historical evidence cannot change current authority.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FTrace%20Closure%20And%20Anti-Drift%20Rule",
          "start_line": 2988
        },
        {
          "end_line": 3049,
          "quote": "Trace closure is stricter than documentation completeness. It is the rule that\ncloses the constitution over realized behavior.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FTrace%20Closure%20And%20Anti-Drift%20Rule%2FDrift%20Signals",
          "start_line": 3048
        }
      ],
      "key": "spec_trace_closure",
      "label": "Constitutional trace closure"
    },
    {
      "conditions": [],
      "definition": "An ADR is durable design memory, organized by the decision that makes acceptance criteria true, rather than by requirement file. It is not another requirement surface.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3206,
          "quote": "**ADRs** are durable design memory. They are not a second requirement surface.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSpecification%20Surface%20Rule",
          "start_line": 3206
        },
        {
          "end_line": 3473,
          "quote": "Write ADRs per decision boundary, not per requirement file.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FADR%20Conventions",
          "start_line": 3473
        }
      ],
      "key": "spec_adr",
      "label": "Architecture decision record"
    },
    {
      "conditions": ["The artifact has been published as a live constitutional surface."],
      "definition": "A live domain surface is versioned constitutional history, immutable in place; a project may accumulate multiple such surfaces.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3058,
          "quote": "The project may accumulate multiple live domain surfaces over time. A live surface is versioned constitutional history, not scratch space.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FLive%20Surface%20Immutability",
          "start_line": 3055
        }
      ],
      "key": "spec_live_surface",
      "label": "Live constitutional surface"
    },
    {
      "conditions": ["A project intentionally abandons a prior constitutional shape and re-derives itself on a new branch, version line, or methodology basis."],
      "definition": "Fundamental migration is a constitutional reset through controlled explicit adoption, rather than an in-place refactor or passive inheritance.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3072,
          "quote": "A fundamental migration is a constitutional reset, not an in-place refactor.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FFundamental%20Migration%20Rule",
          "start_line": 3070
        }
      ],
      "key": "spec_fundamental_migration",
      "label": "Fundamental migration"
    },
    {
      "conditions": [],
      "definition": "Refactor and migration should be understood as transformation waves over mutable implementation surfaces, with an in-flight break boundary and a declared affected landing scope.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3125,
          "quote": "Refactor and migration should be understood as a transformation wave over\nmutable implementation surfaces.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FTransformation%20Wave%20Rule",
          "start_line": 3124
        }
      ],
      "key": "spec_transformation_wave",
      "label": "Transformation wave"
    },
    {
      "conditions": [],
      "definition": "Requirement classification has independent lifecycle and category axes. Lifecycle values are Active, Deferred, Superseded, Orphaned; they concern constitutional membership and operative/deferred standing. Category values are Capability, Constraint / Guarantee, Governance, Verification; they identify the kind of project truth.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3193,
          "quote": "Lifecycle status says whether the requirement still belongs in the constitution and whether it is operative or explicitly deferred. Requirement category says what kind of project truth it asserts.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FRequirement%20Classification%20Rules",
          "start_line": 3178
        }
      ],
      "key": "spec_requirement_classification",
      "label": "Requirement lifecycle and category"
    },
    {
      "conditions": [],
      "definition": "The Product Definition template bootstraps an STDO-defined product through explicit URI bindings. The default definition filename is stdo_default.json for a singleton default project or stdo_<label>.json for a named definition. Its stable product.definition_id identifies the mutable WHAT definition line, distinct from immutable Product and release identities.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 3232,
          "quote": "Every STDO-defined product begins from\n`templates/PRODUCT_DEFINITION_TEMPLATE.json`.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FBootstrap%20Rule",
          "start_line": 3227
        },
        {
          "end_line": 3340,
          "quote": "4. Assign the stable `product.definition_id` for the mutable `WHAT` definition\n   line, its source-project locator, and bounded-context declaration; keep it\n   distinct from every immutable Product and release identity.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FBootstrap%20Rule",
          "start_line": 3338
        }
      ],
      "key": "spec_product_definition",
      "label": "Product Definition bootstrap"
    },
    {
      "conditions": [],
      "definition": "STDO Reference Frame Baseline is an optional specialized role and evaluation profile. Its chosen mappings apply shared law without independently owning execution protocol or Product bindings. Its terms and examples describe a profile, not an activation performed by this interpretation.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1,
          "quote": "# STDO Reference Frame Baseline",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline",
          "start_line": 1
        },
        {
          "end_line": 94,
          "quote": "This document is an optional specialized role and evaluation profile.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FStatus%20And%20Authority%20Boundary",
          "start_line": 91
        }
      ],
      "key": "profile_baseline",
      "label": "STDO Reference Frame Baseline"
    },
    {
      "conditions": [],
      "definition": "An engagement frame is a Reference Frame Method frame evaluating selection, construction, assessment, or disposition of governed work. The profile names Executive, Worker, and Reviewer as overlapping engagement contexts, not an actor hierarchy.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 234,
          "quote": "An **engagement frame** is a `REFERENCE_FRAME_METHOD.md` frame whose evaluation\nfamily concerns selection, construction, assessment, or disposition of governed\nwork. Executive, Worker, and Reviewer are this profile's engagement frames.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FProfile%20Terms%2FEngagement%20frame",
          "start_line": 232
        }
      ],
      "key": "profile_engagement_frame",
      "label": "Engagement frame"
    },
    {
      "conditions": ["Needed by one engagement evaluation.", "Evaluation, basis, material manifold, authority, evidence, result algebra, and capability envelope are declared."],
      "definition": "A specialist frame is an activated Product, requirement, design, identity, release, domain, implementation, test, operational, historical, or capability frame. A method member, file, component, or lens becomes a frame only through the required declaration.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 242,
          "quote": "A method member, file, component, or\nlens becomes a frame only when its evaluation, basis, material manifold,\nauthority, evidence, result algebra, and capability envelope are declared.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FProfile%20Terms%2FSpecialist%20frame",
          "start_line": 240
        }
      ],
      "key": "profile_specialist_frame",
      "label": "Specialist frame"
    },
    {
      "conditions": [],
      "definition": "A generic specialist-frame family is a reusable evaluation archetype, not a complete frame declaration or a selected architecture, owner, carrier, actor, component, or implementation. The twelve chosen families are Product, Product Composition, Design, Design Component, Public Boundary, Entity, Operator, Owner, Effect, Reuse/Foundation, Install, and Proof.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 256,
          "quote": "A **generic specialist-frame family** is a reusable evaluation-family\narchetype in this profile.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FProfile%20Terms%2FGeneric%20specialist-frame%20family",
          "start_line": 246
        },
        {
          "end_line": 57,
          "quote": "This profile also selects twelve generic specialist-frame families: Product,\nProduct Composition, Design, Design Component, Public Boundary, Entity,\nOperator, Owner, Effect, Reuse/Foundation, Install, and Proof.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FCanonical%20Compression",
          "start_line": 49
        }
      ],
      "key": "profile_generic_families",
      "label": "Generic specialist-frame families"
    },
    {
      "conditions": ["A declared subject is executed or observed to discriminate one exact claim."],
      "definition": "A testing frame is a specialist frame with an explicit oracle, evidence population, path boundary, and falsification condition. A test file, suite, runner, fixture, scenario label, coverage percentage, or actor is not a testing frame merely by existing.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 264,
          "quote": "A **testing frame** is a specialist frame whose evaluation executes or observes\na declared subject to discriminate one exact claim through an explicit oracle,\nevidence population, path boundary, and falsification condition.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FProfile%20Terms%2FTesting%20frame",
          "start_line": 260
        }
      ],
      "key": "profile_testing_frame",
      "label": "Testing frame"
    },
    {
      "conditions": [],
      "definition": "The authoritative Product path is the declared ordinary causal composition from supported user or Public entry through exact selected interfaces, owners, state transitions, effects, persistence, recovery, and outcome projection required by the claim.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 275,
          "quote": "An **authoritative Product path** is the declared ordinary causal composition\nfrom a supported user or Public entry through the exact selected interfaces,\nowners, state transitions, effects, persistence and recovery boundaries, and\noutcome projection required by the Product claim.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FProfile%20Terms%2FAuthoritative%20Product%20path",
          "start_line": 272
        }
      ],
      "key": "profile_authoritative_path",
      "label": "Authoritative Product path"
    },
    {
      "conditions": [],
      "definition": "Material combinatorial complexity is the claim-relative population of independent dimensions and interactions whose combinations can change outcomes, violate invariants, select another authority path, or expose failure. Unit dimensions include module-owned public-contract laws, operators, calculation regimes, states, transitions, boundary classes, and failure cases.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 290,
          "quote": "**Material combinatorial complexity** is the claim-relative population of\nindependent dimensions and interactions whose combinations can change an\noutcome, violate an invariant, select another authority path, or expose a\nfailure.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FProfile%20Terms%2FMaterial%20combinatorial%20complexity",
          "start_line": 282
        }
      ],
      "key": "profile_combinatorial_complexity",
      "label": "Material combinatorial complexity"
    },
    {
      "conditions": ["The coordinated branch is selected under existing project authority."],
      "definition": "Executive selects or confirms bounded activation configuration and consumes closed Worker and Reviewer results under existing decision authority. It maintains a sufficient delivery view of long-term outcome, MVP/release mandate, unresolved obligations, dependencies, and exact results for priority, disposition, and next authorized action. The workspace holds the durable frontier; Executive need not load all Product history or worker contexts. A direct human or admitted bounded proxy may occupy it; it is not a universal semantic owner, manager service, controller, or runtime observer.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 306,
          "quote": "**Executive** is the profile label for the frame that selects or confirms the\nbounded activation configuration and consumes closed Worker and Reviewer\nresults under existing project decision authority.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FProfile%20Terms%2FExecutive",
          "start_line": 294
        }
      ],
      "key": "profile_executive",
      "label": "Executive"
    },
    {
      "conditions": ["Successfully activated as a reference frame with sufficient inherited operation authority."],
      "definition": "Worker is the profile's STDO-UP-020 bounded constructor, owning construction and self-review inside exact intake. It acquires no admission, publication, acceptance, or continuation authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 493,
          "quote": "**Worker** is the profile label for `STDO-UP-020`'s bounded constructor role\nwhen activated as a reference frame.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FExecutive%20Attention%2C%20Evaluation%2C%20And%20Action%2FWorker",
          "start_line": 489
        }
      ],
      "key": "profile_worker",
      "label": "Worker"
    },
    {
      "conditions": ["Activated as an independent live-surface evaluation frame."],
      "definition": "Reviewer evaluates one exact subject for the STDO-UP-020 assessment relation under STDO-UP-007 and STDO-UP-022, returning a closed result and evidence-bound technical triage when findings exist. It does not implement repair, assign priority, apply disposition, or activate another frame.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 502,
          "quote": "It\nevaluates one exact subject and returns a closed result with evidence-bound\ntechnical triage when a finding exists.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FExecutive%20Attention%2C%20Evaluation%2C%20And%20Action%2FReviewer",
          "start_line": 499
        }
      ],
      "key": "profile_reviewer",
      "label": "Reviewer"
    },
    {
      "conditions": [],
      "definition": "Technical triage is Reviewer-owned assessment of one finding against exact claim and basis. Severity grades consequence if it manifests; priority orders response against complete outcome, likelihood/exposure, MVP/release mandate, reversibility, dependencies, delay cost, and capacity. Current-boundary effect is Executive's decision that the finding blocks promotion, requires narrowing, or may remain an explicit residual. These are distinct from core evaluation results and execution dispositions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 555,
          "quote": "**Severity** grades consequence if the finding manifests. **Priority** orders\nresponse relative to the complete Product outcome, likelihood and exposure,\ncurrent MVP or release mandate, reversibility, dependencies, cost of delay, and\navailable capacity. Reviewer grades severity. Executive assigns priority.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FExecutive%20Attention%2C%20Evaluation%2C%20And%20Action%2FTechnical%20triage%2C%20severity%2C%20priority%2C%20and%20boundary%20effect",
          "start_line": 512
        }
      ],
      "key": "profile_technical_triage",
      "label": "Technical triage and decision payloads"
    },
    {
      "conditions": ["Successful Worker activation has occurred."],
      "definition": "A work result is closed Worker output to its declared consumer, Executive in the coordinated branch. It carries the shared core record, actual performance and effects, and the exact predicate that requested candidate and transition evidence are available on the activated basis within admitted grant bounds. Domain variants are candidate_ready, refused, incomplete, and re_entry_requested; they are neither another result algebra nor semantic dispositions. activation_refusal produces neither activation nor work result.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 572,
          "quote": "A **work result** is the closed Worker output to its declared consumer; in the\ncoordinated branch that consumer is Executive.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FExecutive%20Attention%2C%20Evaluation%2C%20And%20Action%2FWork%20result",
          "start_line": 559
        }
      ],
      "key": "profile_work_result",
      "label": "Work result"
    },
    {
      "conditions": [],
      "definition": "An exact candidate supplies the subject identity required for STDO-UP-020 transition evidence and STDO-UP-007 review traceability. Where generic-method qualification applies, STDO-UP-022 freezes the construction result before material reference exposure; elsewhere an immutable identity or equivalent exact-subject relation stabilizes the claimed assessment. This creates no constitutional lifecycle state called frozen.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 617,
          "quote": "An **exact candidate** is the subject identity required by `STDO-UP-020`\ntransition evidence and `STDO-UP-007` review traceability.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/STDO_REFERENCE_FRAME_BASELINE.md#STDO%20Reference%20Frame%20Baseline%2FExecutive%20Attention%2C%20Evaluation%2C%20And%20Action%2FExact%20candidate",
          "start_line": 609
        }
      ],
      "key": "profile_exact_candidate",
      "label": "Exact candidate"
    },
